import {DEFAULT_WEIGHTS,FACTORS,scorePerson,currentRole,memberships,CATEGORY_PALETTE,categoryColor,eligibleExternal} from './model.mjs?v=20261117-resume4';
import {createGalaxy,relevanceRadius} from './galaxy.mjs?v=20261117-resume4';
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const communityName=s=>s.replace(/\b\w/g,c=>c.toUpperCase());
const KEY='andi-orbit-v1';
let savedState={};try{savedState=JSON.parse(localStorage.getItem(KEY)||'{}');}catch{}
let weights={...DEFAULT_WEIGHTS,...savedState.weights},annotations=savedState.annotations||{},bookmarks=new Set(savedState.bookmarks||[]),sizePreference=savedState.sizePreference||'all';
let expandedNodes=[],previewOwnerId=null,previewTimer=null,previewClearTimer=null;
let data,nodes=[],edges=[],filtered=[],selected=null,cluster='all',view='map',page=1,hover=null,labels=true;
const groups=[{name:'Brand & graphic',symbol:'◒',x:-580,y:-200,r:235},{name:'Creative leadership',symbol:'✧',x:370,y:-320,r:180},{name:'Motion & media',symbol:'◉',x:-60,y:-430,r:130},{name:'Product & digital',symbol:'▧',x:660,y:-70,r:100},{name:'Talent & recruiting',symbol:'⌁',x:530,y:330,r:235},{name:'Marketing & strategy',symbol:'◇',x:30,y:460,r:185},{name:'BU community',symbol:'⊕',x:-310,y:340,r:120},{name:'Other disciplines',symbol:'⋯',x:-720,y:400,r:290}];
const canvas=$('network');
const persist=()=>{try{localStorage.setItem(KEY,JSON.stringify({weights,annotations,bookmarks:[...bookmarks],sizePreference}));}catch{toast('Browser storage is unavailable. Export a backup to keep changes.');}};
let toastTimer;function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3000);}
function r(n){return relevanceRadius(n.score);}
function selectedOwner(){return selected?.external?nodeMap.get(selected.viaOwner):selected;}
function expansionOwner(){return nodeMap.get(previewOwnerId)||selectedOwner();}
function resetPreview(){clearTimeout(previewTimer);clearTimeout(previewClearTimer);previewOwnerId=null;}
function previewConnection(n){clearTimeout(previewTimer);clearTimeout(previewClearTimer);if(n?.external)return;if(n){previewTimer=setTimeout(()=>{previewOwnerId=n.id;updateExpansion();invalidate();},150);}else{previewClearTimer=setTimeout(()=>{previewOwnerId=null;updateExpansion();invalidate();},320);}}
function updateExpansion(){const owner=expansionOwner();expandedNodes=owner?eligibleExternal(data.discovery,owner.id,nodes,weights,annotations,sizePreference).map(n=>({...n,radius:r(n)})).filter(candidateMatches):[];}
function calculate(){for(const n of nodes){Object.assign(n,scorePerson(n,weights,annotations[n.id],sizePreference));n.displayCategories=memberships(n,annotations[n.id]);n.radius=r(n);}if(selected?.external){Object.assign(selected,scorePerson(selected,weights,annotations[selected.id],sizePreference));selected.displayCategories=memberships(selected,annotations[selected.id]);}filtered=nodes.filter(matches);updateExpansion();page=1;updateUI();invalidate();if(selected)renderDetail();}
function matches(n){return matchesScope(n,false);}
function candidateMatches(n){return matchesScope(n,true);}
function matchesScope(n,ignoreSearch){const q=$('search').value.trim().toLowerCase();const level=$('levelFilter').value;return (cluster==='all'||n.displayCategories.includes(cluster))&&(ignoreSearch||!q||`${n.name} ${n.headline} ${n.organization||''}`.toLowerCase().includes(q))&&(!$('buOnly').checked||n.bu||annotations[n.id]?.alumni==='yes')&&(!$('savedOnly').checked||bookmarks.has(n.id))&&n.score>=Number($('minScore').value)&&(level==='all'||level==='leaders'&&n.level>=5||level==='managers'&&n.level===4||level==='contributors'&&[2,3].includes(n.level)||level==='students'&&n.level===1||level==='unknown'&&n.level===0);}
function updateUI(){enhanceSelects();const coverage=$('discoveryCoverage');if(coverage){const m=data.discovery?.meta||{},round=m.latestRound;coverage.textContent=`${m.profilesReviewed||m.listsChecked||0} of ${nodes.length} captured contacts reviewed; ${m.listsChecked||0} list searches, ${m.limitedVisibility||0} profiles with limited list visibility, and ${m.unreviewedProfiles??nodes.length} profiles still unreviewed. ${m.externalPeople||0} distinct external profiles and ${data.discovery?.links.length||0} evidenced links. ${round?'Latest sweep: '+round.owners.length+' contacts reviewed, '+round.pages+' result pages and '+round.rows+' rows captured. ':''}${m.collectionStatus==='search_paused'?'LinkedIn paused search; collection stopped. ':m.collectionStatus==='authentication_required'?'Collection paused because LinkedIn required sign-in. ':m.collectionStatus==='stopped_by_user'?'Sweep stopped at your request after LinkedIn required sign-in again. ':'Coverage is partial. '}An opening-page sample is not a complete network, and unobserved networks remain unknown.`;}const counts={};for(const n of nodes)for(const category of n.displayCategories)counts[category]=(counts[category]||0)+1;$('clusterFilters').innerHTML=[{name:'all',symbol:'◎'},...groups].map(g=>`<button class="cluster-button ${cluster===g.name?'active':''}" data-cluster="${g.name}" aria-pressed="${cluster===g.name}"><span class="cluster-symbol" style="--category-color:${CATEGORY_PALETTE[g.name]?.light||'#bcbcbc'}" aria-hidden="true"></span><span>${g.name==='all'?'All Connections':communityName(g.name)}</span><span>${g.name==='all'?nodes.length:counts[g.name]||0}</span></button>`).join('');$('visibleCount').textContent=`${filtered.length} ${filtered.length===1?'person':'people'} mapped`;$('allCount').textContent=nodes.length;$('mutualCount').textContent=edges.length;$('navCount').textContent=nodes.length;$('listCount').textContent=`${filtered.length} of ${nodes.length} people · scores are estimates, not job probabilities`;$('minOutput').textContent=$('minScore').value;const progress=document.querySelector('.range-progress img');if(progress){progress.style.transformOrigin='left center';progress.style.transform='scaleX('+($('minScore').clientWidth*Number($('minScore').value)/100/47)+')';}$('legendHint').textContent=cluster==='all'?'Mingled hues indicate multiple categories':'Hue: '+communityName(cluster);$('legendGradient').style.background=cluster==='all'?'linear-gradient(90deg,#30343b,#b9ffe3)':'linear-gradient(90deg,'+CATEGORY_PALETTE[cluster].dark+','+CATEGORY_PALETTE[cluster].light+')';if(view==='list')renderTable();}
const galaxy=createGalaxy(canvas,{getState:()=>({nodes,edges,filtered,selected:selectedOwner(),inspectedId:selected?.external?selected.id:null,expanded:expandedNodes,expandedOwner:expansionOwner()?.id,previewExpansion:!!previewOwnerId&&previewOwnerId!==selectedOwner()?.id,detailOpen:!$('detail').hidden,cluster,labels,saved:bookmarks,spokes:$('showSpokes').checked,mutuals:$('showMutuals').checked,active:view==='map'}),onSelect:id=>selectPerson(id),onClear:closeDetail,onHover:previewConnection,onTooltip:(n,p)=>{const tt=$('tooltip');if(!n){tt.hidden=true;return;}tt.innerHTML=`<strong>${esc(n.name)}</strong><p>${esc(n.headline.slice(0,135))}</p><span class="tt-score">${n.score}/100 estimated relevance</span><p>${esc(n.levelLabel)}</p>`;tt.hidden=false;tt.style.left=Math.max(8,Math.min(p.x+17,canvas.clientWidth-260))+'px';tt.style.top=Math.max(8,Math.min(p.y+17,canvas.clientHeight-145))+'px';},onZoom:ratio=>$('zoomValue').textContent=ratio<1.08?'GALAXY':ratio.toFixed(1)+'×'});
function layout(){galaxy.setNodes(nodes);}function resize(){galaxy.resize();}function recenter(){closeDetail();galaxy.reset();}function fit(){galaxy.fit();}function zoom(factor){galaxy.zoom(factor);}function invalidate(){galaxy.invalidate();}function draw(){galaxy.renderNow();}
let nodeMap=new Map();
function selectPerson(id){const candidate=expandedNodes.find(n=>n.id===id)||nodeMap.get(id);resetPreview();selected=candidate;if(!selected)return;if(selected.external&&!selected.viaOwner){const link=data.discovery.links.find(e=>e.target===selected.id);selected={...selected,...scorePerson(selected,weights,annotations[selected.id],sizePreference),viaOwner:link?.source,evidence:link?.evidence,displayCategories:memberships(selected,annotations[selected.id])};selected.radius=r(selected);}updateExpansion();renderDetail();if(view==='map'){if($('search').value){$('search').value='';calculate();}if(selected.external)galaxy.focus(id);else if(expandedNodes.length)galaxy.fitExpanded();else galaxy.focus(id);}invalidate();$('tooltip').hidden=true;}
function closeDetail(){resetPreview();selected=null;updateExpansion();$('detail').hidden=true;invalidate();}
function expansionPanel(owner){const review=data.discovery?.reviews?.[owner.id],status=review?.status||'not_checked',messages={partial:'Partially captured. LinkedIn paused search before the full list could be reviewed.',mutual_only:'Only mutual links were visible. The external network could not be captured.',mutual_evidence:'Observed mutual-card links only; this person’s own list has not been checked.',sampled:'A sample of this connection’s visible list was captured. Remaining pages have not been reviewed.',limited_visibility:'The profile exposes mutual connections only; its external connection list is not accessible.',list_unavailable:'No accessible connection-list link was exposed on this profile.',no_results:'The visible list search returned no results. Its full network is still unknown.',not_checked:'This connection’s list has not been checked. Its extended network is unknown.'},people=eligibleExternal(data.discovery,owner.id,nodes,weights,annotations,sizePreference).filter(candidateMatches);return `<section class="expanded-summary"><h3>Beyond your connections</h3><p>${people.length} observed ${people.length===1?'person':'people'} with relevance above 60 · current filters${people.length?' · shown in the adjacent cloud':''}</p><p class="detail-note">${esc(review?.round>=3?review.note:messages[status]||'Observed records only; coverage is partial.')}</p>${people.length?'<button id="viewExpandedCloud" class="outline-button">View adjacent cloud ↗</button>':''}${people.length?`<details><summary>Browse ${people.length} people</summary>${people.map(p=>`<button class="mutual-person" data-person="${p.id}">${esc(p.name)}<span>${p.score}/100 ↗</span></button>`).join('')}</details>`:''}<p class="detail-note">Reviewed ${data.discovery?.meta.profilesReviewed||data.discovery?.meta.listsChecked||0} of ${nodes.length} captured contacts: ${data.discovery?.meta.listsChecked||0} list searches and ${data.discovery?.meta.limitedVisibility||0} profiles with limited list visibility. Searches are partial. ${data.discovery?.meta.externalPeople||0} distinct external profiles observed; unobserved networks are unknown.</p></section>`;}
function renderDetail(){if(!selected)return;const n=selected,a=annotations[n.id]||{},role=currentRole(n),mutuals=(n.external?data.discovery.links:edges).filter(e=>e.source===n.id||e.target===n.id).map(e=>({node:nodeMap.get(e.source===n.id?e.target:e.source),evidence:e.evidence})).sort((a,b)=>b.node.score-a.node.score);$('detail').hidden=false;
$('detail').innerHTML=`<div class="detail-top"><span class="eyebrow">NETWORK ATLAS · ${n.external?'OBSERVED SECOND DEGREE':'FIRST DEGREE'}</span><button id="closeDetail" aria-label="Close person details">×</button></div><div class="person-mark">${esc(n.name.split(/\s+/).map(x=>Array.from(x)[0]).slice(0,2).join(''))}</div><h2 tabindex="0" data-person-name="${n.id}">${esc(n.name)}</h2><div class="detail-role" title="${esc(role.source)}"><p class="detail-title">${esc(role.title||'Title not listed')}</p><p class="detail-company">${esc(role.company||'Company not listed')}</p></div>${n.headline&&n.headline!==role.title?`<p class="detail-headline">${esc(n.headline)}</p>`:''}<div class="tags">${n.displayCategories.map(c=>`<span class="tag category-tag" title="${esc(n.categoryEvidence?.find(e=>e.category===c)?n.categoryEvidence.find(e=>e.category===c).evidence+' · '+n.categoryEvidence.find(e=>e.category===c).confidence:'Confirmed BU affiliation')}" style="--category-color:${CATEGORY_PALETTE[c].light}">${esc(communityName(c))}</span>`).join('')}${n.bu?'<span class="tag bu">BU tie</span>':''}${n.alumni?'<span class="tag bu">Explicit BU alumnus</span>':''}</div><div class="score-block"><div><span class="eyebrow">ESTIMATED RELEVANCE</span><p>${n.coverage}% of factor weight has a signal</p></div><strong>${n.score}<span>/100</span></strong></div>${Object.entries(FACTORS).map(([key,label])=>`<div class="factor"><div><span>${label}</span><small>${n.signals[key]===null?'Unknown · neutral':Math.round(n.signals[key]*100)+'% signal'} · w${weights[key]}</small></div><div class="bar ${n.signals[key]===null?'unknown':''}"><i style="width:${(n.signals[key]??.5)*100}%"></i></div></div>`).join('')}<p class="detail-note">${esc(n.levelLabel)} · headline estimate<br>BU alumni: ${a.alumni==='yes'?'Confirmed by you':a.alumni==='no'?'Not an alumnus, confirmed by you':n.alumni?'Explicit in headline':'Unknown; BU affiliation alone is not alumni status'}<br>Organization: ${esc(a.size&&a.size!=='unknown'?a.size+' · entered by you':n.orgSizeRange||'Size unknown')}${n.orgIndustry?'<br>Company industry: '+esc(n.orgIndustry):''}</p>${n.orgSource?`<a class="evidence-link" href="${esc(n.orgSource)}" target="_blank" rel="noopener noreferrer">Company size source ↗</a>`:''}<div class="detail-actions"><a class="primary-button" href="${esc(n.url)}" target="_blank" rel="noopener noreferrer">View LinkedIn profile ↗</a><button id="savePerson" class="outline-button">${bookmarks.has(n.id)?'★ Saved':'☆ Save'}</button></div><p class="detail-note">${n.external?'Observed '+esc(n.observedDate)+' via '+esc(nodeMap.get(n.viaOwner)?.name||'your connection'): 'Connected '+esc(n.connected)}. Opportunity signals suggest a conversation; they do not verify a current vacancy or referral willingness.</p>${n.external?`<p class="detail-note">Not a first-degree connection in the observed LinkedIn result. <a href="${esc(n.evidence)}" target="_blank" rel="noopener noreferrer">View connection evidence ↗</a></p><button class="outline-button" data-person="${n.viaOwner}">Back to ${esc(nodeMap.get(n.viaOwner)?.name||'connection')}’s cloud ↗</button>`:expansionPanel(n)}<h3>${mutuals.length} observed ${mutuals.length===1?'connection':'connections'} in your network</h3>${mutuals.length?mutuals.slice(0,8).map(m=>`<button class="mutual-person" data-person="${m.node.id}">${esc(m.node.name)}<span>↗</span></button>`).join(''):'<p class="detail-note">No cross-links captured for this person. Their mutual network has not been fully checked.</p>'}${mutuals.length?`<a class="evidence-link" href="${esc(mutuals[0].evidence)}" target="_blank" rel="noopener noreferrer">View observed mutual-link evidence ↗</a>`:''}<h3>Your confirmed context</h3><div class="context-fields"><label>BU alumnus<select id="personAlumni"><option value="unknown">Unknown / use headline</option><option value="yes">Yes · confirmed by me</option><option value="no">No · confirmed by me</option></select></label><label>Organization size<select id="personSize"><option value="">Use sourced data</option><option value="unknown">Unknown</option><option value="small">Small · up to 50</option><option value="medium">Mid-size · 51–1,000</option><option value="large">Large · 1,001+</option></select></label><label class="full">Opportunity context<select id="personOpportunity"><option value="unknown">Use headline estimate</option><option value="1">Confirmed relevant hiring / referral contact</option><option value="0.7">Relevant peer or introduction</option><option value="0.3">Limited relevance for this search</option><option value="0">No current job-search relevance</option></select></label><label class="full">Private notes<textarea id="personNotes" placeholder="Where you met, a shared project, your next step…">${esc(a.notes||'')}</textarea></label></div><p class="detail-note">Your edits stay in this browser. Export a backup to retain them.</p>`;
const cloudButton=$('viewExpandedCloud');if(cloudButton)cloudButton.onclick=()=>{$('detail').hidden=true;galaxy.fitExpanded();invalidate();};$('personAlumni').value=a.alumni||'unknown';$('personSize').value=a.size||'';$('personOpportunity').value=a.opportunity??'unknown';$('closeDetail').onclick=closeDetail;$('savePerson').onclick=()=>toggleSave(n.id);
for(const [id,key] of [['personAlumni','alumni'],['personSize','size'],['personOpportunity','opportunity']])$(id).onchange=e=>{annotations[n.id]={...annotations[n.id],[key]:e.target.value};persist();calculate();};$('personNotes').oninput=e=>{annotations[n.id]={...annotations[n.id],notes:e.target.value};persist();};enhanceSelects();}
function toggleSave(id){if(bookmarks.has(id))bookmarks.delete(id);else bookmarks.add(id);persist();filtered=nodes.filter(matches);updateUI();if(selected)renderDetail();invalidate();}
function sorted(){const key=$('sortSelect').value;return [...filtered].sort((a,b)=>key==='name'?a.name.localeCompare(b.name):key==='level'?b.level-a.level||b.score-a.score:key==='recent'?Date.parse(b.connected)-Date.parse(a.connected):b.score-a.score||a.name.localeCompare(b.name));}
function renderTable(){const list=sorted(),pages=Math.max(1,Math.ceil(list.length/30));page=Math.max(1,Math.min(page,pages));$('connectionsTable').innerHTML=list.slice((page-1)*30,page*30).map(n=>`<tr><td><button class="person-link" data-person="${n.id}">${esc(n.name)}</button><p>${esc(n.headline)}</p></td><td>${n.displayCategories.map(c=>`<span class="table-category" style="--category-color:${CATEGORY_PALETTE[c].light}">${esc(communityName(c))}</span>`).join('')}${n.bu?'<p>Boston University tie</p>':''}</td><td>${esc(n.levelLabel)}</td><td><span class="table-score">${n.score}</span><p>${n.coverage}% signal coverage</p></td><td><button class="save-star ${bookmarks.has(n.id)?'saved':''}" data-save="${n.id}" aria-label="${bookmarks.has(n.id)?'Unsave':'Save'} ${esc(n.name)}">${bookmarks.has(n.id)?'★':'☆'}</button></td></tr>`).join('')||'<tr><td colspan="5">No connections match your filters. Reset filters to see the full network.</td></tr>';$('pageLabel').textContent=`Page ${page} of ${pages} · ${list.length} ${list.length===1?'person':'people'}`;$('prevPage').disabled=page===1;$('nextPage').disabled=page===pages;}
function setView(next){view=next;$('mapView').hidden=next!=='map';$('listView').hidden=next!=='list';$('mapTab').classList.toggle('active',next==='map');$('listTab').classList.toggle('active',next==='list');if(next==='list')renderTable();else{if(selected&&$('search').value){$('search').value='';calculate();}resize();if(selected){if(expandedNodes.length&&!selected.external)galaxy.fitExpanded();else galaxy.focus(selected.id);}}}
function showDialog(id){$(id).showModal();enhanceSelects();}
function resetFilters(){cluster='all';$('search').value='';$('levelFilter').value='all';$('buOnly').checked=false;$('savedOnly').checked=false;$('minScore').value=20;calculate();}
function renderWeights(){$('weightSliders').innerHTML=Object.entries(FACTORS).map(([key,label])=>`<div class="weight-row"><label for="weight-${key}">${label}<output id="output-${key}">${weights[key]}</output></label><input id="weight-${key}" data-weight="${key}" type="range" min="0" max="60" step="5" value="${weights[key]}"></div>`).join('');$('sizePreference').value=sizePreference;enhanceSelects();}
function download(content,name,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Download prepared.');}
const csv=v=>{let text=String(v??'');if(/^[=+@-]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"';};
function bind(){
$('mapTab').onclick=()=>setView('map');$('listTab').onclick=()=>setView('list');$('clearFilters').onclick=resetFilters;
$('clusterFilters').onclick=e=>{const b=e.target.closest('[data-cluster]');if(b){cluster=b.dataset.cluster;calculate();}};
for(const id of ['search','levelFilter','buOnly','savedOnly','minScore'])$(id).addEventListener(id==='search'||id==='minScore'?'input':'change',calculate);
$('pauseMotion').onclick=()=>{const paused=$('pauseMotion').getAttribute('aria-pressed')!=='true';$('pauseMotion').setAttribute('aria-pressed',paused);$('pauseMotion').textContent=paused?'Resume motion':'Pause motion';galaxy.setPaused(paused);};$('labelsButton').onclick=()=>{labels=!labels;$('labelsButton').classList.toggle('active',labels);$('labelsButton').setAttribute('aria-pressed',labels);invalidate();};$('showSpokes').onchange=invalidate;$('showMutuals').onchange=invalidate;
$('zoomIn').onclick=()=>zoom(1.25);$('zoomOut').onclick=()=>zoom(.8);$('recenter').onclick=recenter;$('fitAll').onclick=fit;
$('mobileFilterButton').onclick=()=>{const expanded=document.querySelector('.sidebar').classList.toggle('expanded');$('mobileFilterButton').setAttribute('aria-expanded',expanded);};$('visibleCount').onclick=()=>showDialog('method');$('weightsButton').onclick=()=>showDialog('settings');$('methodButton').onclick=()=>showDialog('method');$('coverageButton').onclick=()=>showDialog('method');$('exportButton').onclick=()=>showDialog('exportDialog');
for(const btn of document.querySelectorAll('[data-close]'))btn.onclick=()=>$(btn.dataset.close).close();
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close();}});
$('weightSliders').addEventListener('input',e=>{const key=e.target.dataset.weight;if(key){weights[key]=Number(e.target.value);$('output-'+key).textContent=weights[key];persist();calculate();}});$('sizePreference').onchange=e=>{sizePreference=e.target.value;persist();calculate();};$('resetWeights').onclick=()=>{weights={...DEFAULT_WEIGHTS};sizePreference='all';renderWeights();persist();calculate();};
$('sortSelect').onchange=()=>{page=1;renderTable();};$('prevPage').onclick=()=>{page--;renderTable();};$('nextPage').onclick=()=>{page++;renderTable();};
document.addEventListener('click',e=>{const p=e.target.closest('[data-person]'),s=e.target.closest('[data-save]');if(p)selectPerson(p.dataset.person);if(s)toggleSave(s.dataset.save);});
function hoverPersonElement(e){return e.target.closest?.('[data-person],[data-person-name]');}
for(const event of ['pointerover','focusin'])document.addEventListener(event,e=>{const el=hoverPersonElement(e);if(el)galaxy.setHovered(el.dataset.person||el.dataset.personName);});
for(const event of ['pointerout','focusout'])document.addEventListener(event,e=>{const el=hoverPersonElement(e);if(el&&!el.contains(e.relatedTarget))galaxy.setHovered(null);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeDetail();return;}if(e.target.matches('input,select,textarea')||document.querySelector('dialog[open]'))return;if(e.key==='/'){e.preventDefault();$('search').focus();}if(e.key==='Home'){e.preventDefault();recenter();}if(['+','='].includes(e.key))zoom(1.2);if(e.key==='-')zoom(1/1.2);if(document.activeElement===canvas&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();if(e.metaKey)galaxy.rotate(e.key==='ArrowLeft'?-.16:e.key==='ArrowRight'?.16:0,e.key==='ArrowUp'?.12:e.key==='ArrowDown'?-.12:0);else galaxy.pan(e.key==='ArrowLeft'?50:e.key==='ArrowRight'?-50:0,e.key==='ArrowUp'?50:e.key==='ArrowDown'?-50:0);invalidate();}});
$('exportCSV').onclick=()=>{const header=['Name','Headline','LinkedIn','Connected','Category estimates (nonexclusive)','Seniority estimate','Relevance estimate','Signal coverage %','BU headline tie','BU alumni','Organization size','Saved','Notes'];download('\uFEFF'+[header,...sorted().map(n=>[n.name,n.headline,n.url,n.connected,n.displayCategories.join('; '),n.levelLabel,n.score,n.coverage,n.bu?'yes':'unknown',annotations[n.id]?.alumni||(n.alumni?'explicit in headline':'unknown'),annotations[n.id]?.size||n.orgSizeRange||'unknown',bookmarks.has(n.id)?'yes':'no',annotations[n.id]?.notes||''])].map(row=>row.map(csv).join(',')).join('\r\n'),'andi-network-connections.csv','text/csv;charset=utf-8');};
$('exportJSON').onclick=()=>download(JSON.stringify({schema:'andi-orbit-v1',...data,preferences:{weights,sizePreference,annotations,bookmarks:[...bookmarks]}},null,2),'andi-network-atlas-backup.json','application/json');
$('exportPNG').onclick=()=>{if(view!=='map'){setView('map');}$('exportDialog').close();draw();canvas.toBlob(blob=>{if(blob)download(blob,'andi-network-atlas.png','image/png');});};
$('importJSON').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>15_000_000)throw Error('This backup is too large.');const backup=JSON.parse(await file.text());if(backup.schema!=='andi-orbit-v1'||!backup.preferences)throw Error('Choose a Network Atlas backup.');const p=backup.preferences;if(p.weights)for(const key of Object.keys(DEFAULT_WEIGHTS)){const v=Number(p.weights[key]);if(!Number.isFinite(v)||v<0||v>60)throw Error('Invalid scoring weights.');}if(!Array.isArray(p.bookmarks)||!p.annotations||typeof p.annotations!=='object'||Array.isArray(p.annotations))throw Error('Invalid preferences.');weights={...DEFAULT_WEIGHTS,...p.weights};sizePreference=['all','small','medium','large'].includes(p.sizePreference)?p.sizePreference:'all';bookmarks=new Set(p.bookmarks.filter(id=>nodeMap.has(id)));annotations=Object.fromEntries(Object.entries(p.annotations).filter(([id,a])=>nodeMap.has(id)&&a&&typeof a==='object').map(([id,a])=>[id,{notes:String(a.notes||'').slice(0,20000),alumni:['yes','no','unknown'].includes(a.alumni)?a.alumni:'unknown',size:['small','medium','large','unknown',''].includes(a.size)?a.size:'',opportunity:['unknown','1','0.7','0.3','0'].includes(String(a.opportunity))?String(a.opportunity):'unknown'}]));persist();renderWeights();calculate();$('importStatus').textContent='Restored your preferences and annotations for this network.';}catch(error){$('importStatus').textContent=error.message;}e.target.value='';};
new ResizeObserver(()=>{if(view==='map')resize();}).observe($('mapView'));
}
const selectNames={levelFilter:'Seniority',sortSelect:'Sort by',sizePreference:'Preferred organization size',personAlumni:'BU alumnus',personSize:'Organization size',personOpportunity:'Opportunity context'};
let openSelectMenu=null;
function closeSelectMenu(returnFocus=false){if(!openSelectMenu)return;const {menu,trigger}=openSelectMenu;menu.remove();trigger.setAttribute('aria-expanded','false');trigger.removeAttribute('aria-controls');openSelectMenu=null;if(returnFocus&&trigger.isConnected)trigger.focus();}
function enhanceSelects(){
 if(openSelectMenu&&!openSelectMenu.select.isConnected)closeSelectMenu();
 for(const select of document.querySelectorAll('select')){
  let wrap=select.nextElementSibling;
  if(!wrap?.classList.contains('atlas-select')){
   select.hidden=true;select.tabIndex=-1;wrap=document.createElement('span');wrap.className='atlas-select';const trigger=document.createElement('button');trigger.type='button';trigger.className='atlas-select-trigger';trigger.setAttribute('role','combobox');trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');trigger.setAttribute('aria-label',selectNames[select.id]||select.id);wrap.append(trigger);select.after(wrap);
   const open=(direction=0)=>{
    closeSelectMenu();const menu=document.createElement('div');menu.className='atlas-select-menu';menu.setAttribute('role','listbox');menu.setAttribute('aria-label',selectNames[select.id]||select.id);menu.id='options-'+select.id;trigger.setAttribute('aria-controls',menu.id);trigger.setAttribute('aria-expanded','true');
    const choices=[...select.options].filter(o=>!o.disabled),buttons=choices.map(option=>{const button=document.createElement('button');button.type='button';button.className='atlas-select-option';button.setAttribute('role','option');button.setAttribute('aria-selected',String(select.value===option.value));button.textContent=option.text;button.onclick=()=>{select.value=option.value;closeSelectMenu(true);select.dispatchEvent(new Event('change',{bubbles:true}));enhanceSelects();};menu.append(button);return button;});
    (select.closest('dialog')||document.body).append(menu);const rect=trigger.getBoundingClientRect(),height=Math.min(menu.scrollHeight,280),room=innerHeight-rect.bottom;menu.style.width=Math.max(rect.width,180)+'px';menu.style.left=Math.max(8,Math.min(rect.left,innerWidth-Math.max(rect.width,180)-8))+'px';menu.style.top=(room<height&&rect.top>height?Math.max(8,rect.top-height-4):Math.min(innerHeight-height-8,rect.bottom+4))+'px';
    openSelectMenu={select,menu,trigger};let index=Math.max(0,choices.findIndex(o=>o.value===select.value));if(direction)index=Math.max(0,Math.min(buttons.length-1,index+direction));buttons[index]?.focus();
    let typed='',typeTimer;menu.onkeydown=e=>{e.stopPropagation();let next=buttons.indexOf(document.activeElement);if(e.key==='Escape'){e.preventDefault();closeSelectMenu(true);return;}if(e.key==='Tab'){closeSelectMenu();return;}if(e.key==='ArrowDown')next=Math.min(buttons.length-1,next+1);else if(e.key==='ArrowUp')next=Math.max(0,next-1);else if(e.key==='Home')next=0;else if(e.key==='End')next=buttons.length-1;else if(e.key.length===1&&!e.metaKey&&!e.ctrlKey){typed+=e.key.toLowerCase();clearTimeout(typeTimer);typeTimer=setTimeout(()=>typed='',650);const found=choices.findIndex(o=>o.text.toLowerCase().startsWith(typed));if(found>=0)next=found;else return;}else return;e.preventDefault();buttons[next]?.focus();};
   };
   trigger.onclick=()=>openSelectMenu?.select===select?closeSelectMenu(true):open();trigger.onkeydown=e=>{if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();e.stopPropagation();open(e.key==='ArrowDown'?1:-1);}else if(e.key==='Escape')closeSelectMenu(true);};
  }
  const trigger=wrap.querySelector('button');trigger.textContent=select.selectedOptions[0]?.text||'';trigger.disabled=select.disabled;
 }
}
document.addEventListener('pointerdown',e=>{if(openSelectMenu&&!openSelectMenu.menu.contains(e.target)&&!openSelectMenu.trigger.contains(e.target))closeSelectMenu();});
window.addEventListener('resize',()=>closeSelectMenu());document.addEventListener('scroll',e=>{if(openSelectMenu&&!openSelectMenu.menu.contains(e.target))closeSelectMenu();},true);

async function init(){try{const response=await fetch('./data.json');if(!response.ok)throw Error('Network data could not be loaded.');data=await response.json();nodes=data.nodes;edges=data.edges;nodeMap=new Map([...nodes,...(data.discovery?.nodes||[])].map(n=>[n.id,n]));for(const n of nodes){Object.assign(n,scorePerson(n,weights,annotations[n.id],sizePreference));n.displayCategories=memberships(n,annotations[n.id]);n.radius=r(n);}layout();renderWeights();bind();calculate();resize();$('loading').hidden=true;}catch(error){$('loading').innerHTML=`<p>${esc(error.message)}</p><p>Reload the page to try again.</p>`;console.error(error);}}
init();
